  'rerere.intro': 'Git kan onthouden hoe je een conflict oploste en dat afspelen zodra hetzelfde conflict weer opduikt. Het verdient zichzelf terug op een langlopende branch die keer op keer door dezelfde botsing heen gerebaset wordt — je lost hem dan één keer op.',
