  'replace.title': 'Vervangen & enten',
  'replace.intro':
    'git replace zegt tegen git dat het het ene object moet lezen waar om het andere gevraagd werd. Er wordt niets herschreven en geen enkele sha verandert — en dat maakt het de eerlijke manier om een kloon in te korten: ent een commit op geen enkele parent en alles daarvóór valt uit elke walk weg, nog altijd opgeslagen, nog altijd terug te zetten.',
  'replace.none': 'Geen vervangingen. Git laat je precies zien wat er opgeslagen staat.',
