  'attrs.title': 'Bestandsattributen',
  'attrs.intro':
    '.gitattributes is hoe een repository git over zijn eigen bestanden vertelt: welke binair zijn, welke aan elkaar geplakt moeten worden in plaats van te conflicteren, welke buiten een archief blijven en welke regeleindes gebruikt worden. Het reist mee met de kloon, dus wat je hier repareert, repareer je voor iedereen.',
  'attrs.none': 'Nog geen regels. De voorinstellingen hieronder dekken de gevallen die het vaakst voorkomen.',
  'attrs.localFile':
    'Dit bestand staat in .git/info/ — het geldt alleen op deze machine en wordt nooit gecommit of gedeeld.',
