  'attrs.checkTitle': 'Wat geldt er voor een pad?',
  'attrs.checkHint':
    'Regels komen uit meerdere bestanden en de laatste treffer wint, dus ze lezen is gokwerk. Dit vraagt het aan git zelf.',
  'attrs.check': 'Controleren',
  'attrs.checkNothing': 'Voor dit pad is niets ingesteld.',
  'attrs.driversTitle': 'Diff-drivers',
  'attrs.driversHint':
    'Een diff-driver zet een onleesbaar bestand om in tekst voordat git het vergelijkt, zodat een Word-document of spreadsheet een leesbare geschiedenis heeft. Word, Excel en JSON gebruiken de converter die GitHuttBr meelevert; de rest wordt aangeboden indien geïnstalleerd en anders grijs weergegeven.',
  'attrs.driverMissing': 'converter niet geïnstalleerd',
  'attrs.needsBinary': 'Vereist {binary} in je PATH.',
  'attrs.bundledConverter': 'Meegeleverd met GitHuttBr — niets te installeren.',
  'attrs.driverEphemeral': "wijst naar een tijdelijke AppImage-map",
  'attrs.driverEphemeralHint': "Een AppImage-versie van GitHuttBr heeft deze converter ingesteld. De map onder /tmp verdwijnt zodra de app stopt, en elke andere gebruiker op deze machine kan daar een programma neerzetten dat je volgende git diff uitvoert. Verwijder hem.",
  'attrs.driverStale': 'converter is van vóór 4.39',
  'attrs.driverStaleHint': 'Deze converter is degene die versies tot en met 4.38 onder de oude naam van de app meeleverden. De app zet zulke drivers zelf om naar zijn huidige converter; bij deze lukte dat niet: het pad van een AppImage verandert bij elke start, of de configuratie kon niet worden geschreven. Diffs van deze bestanden mislukken, tenzij de oude installatie er nog staat. Verwijder hem en voeg de driver daarna opnieuw toe vanuit de suggesties hieronder.',
  'attrs.driverRemove': "Verwijderen",
  'attrs.bundledAppImage': "Niet beschikbaar in de AppImage: de converter van GitHuttBr bestaat alleen zolang de app draait. Installeer het .deb-pakket om hem te gebruiken.",
  'attrs.filtersTitle': 'Clean/smudge-filters',
  'attrs.filtersHint': 'Een filter herschrijft bestandsinhoud op weg naar binnen (clean, bij het stagen) en op weg naar buiten (smudge, bij checkout) — zo werken git-lfs en het strippen van sleutels. Een verkeerd filter beschadigt je working tree geruisloos, dus GitHuttBr eist eerst een proefrun tegen echte bestanden voordat er iets wordt opgeslagen.',
  'attrs.filterCleanPh': 'clean-commando (stdin → stdout)',
  'attrs.filterSmudgePh': 'smudge-commando (optioneel)',
  'attrs.filterRequired': 'Vereist — de operatie mislukt in plaats van bestanden ongewijzigd door te laten',
  'attrs.filterDryRun': 'Proefrun',
  'attrs.filterDryRunFirst': 'Draai eerst de proefrun met precies deze waarden.',
  'attrs.filterSave': 'Filter opslaan',
  'attrs.filterNoMatches': 'Geen enkel getrackt bestand past op dit patroon — er kon niets worden getest.',
  'attrs.filterMatched': 'Overeenkomende bestanden: {n} · getest: {m}.',
  'attrs.filterRoundtripOk': 'roundtrip OK — smudge(clean(file)) levert het origineel weer op',
  'attrs.filterRoundtripDifferent': 'roundtrip wijkt af — een checkout zou niet de originele bytes terugzetten',
  'attrs.filterRoundtripSkipped': 'clean draaide — geen smudge-commando, dus geen roundtrip-controle',
  'attrs.filterDangerTitle': 'Ongeverifieerd filter opslaan?',
  'attrs.filterDangerMessage': 'De proefrun kon "{name}" niet verifiëren: een commando faalde, niets kwam overeen, of de roundtrip levert niet de originele bytes op. Als het filter fout is, kan elke checkout van passende bestanden je working tree geruisloos beschadigen.',
  'attrs.filterDangerConfirm': 'Toch opslaan',
  'attrs.filterRemoveTitle': 'Filter verwijderen?',
  'attrs.filterRemoveMessage': 'Dit wist filter.{name}.clean/smudge uit je git-configuratie. .gitattributes-regels die ernaar verwijzen blijven staan; zonder required gaan passende bestanden dan ongewijzigd door.',
