  'keychain.pointStore': 'Alleen wat je in GitHuttBr typte wordt versleuteld: je tokens voor Git-hosts, je AI-API-sleutel en je kluisitems.',
  'keychain.pointNoAccess': 'GitHuttBr kan niets anders in je keychain lezen. Het systeem geeft een app alleen ooit het ene item terug dat die app zelf aanmaakte.',
