  'keychain.whatHappensAdopted': 'Er verandert niets als je doorgaat: GitHuttBr leest het item terug dat het zelf al aanmaakte. Je besturingssysteem kan na een update nog één keer om bevestiging vragen, omdat de app die het ziet veranderd is.',
