  'keychain.storeUnreadable': 'GitHuttBr kon je opgeslagen tokens niet lezen — de keychain was vergrendeld of toegang werd geweigerd. Ze zijn onaangeroerd. Ontgrendel de keychain en probeer het opnieuw; tokens die je intussen toevoegt, blijven alleen bewaard tot je afsluit.',
  'keychain.weakBackend': 'Er draait geen sleutelhanger (GNOME Keyring of KWallet), dus het systeem valt terug op eenvoudige opslag, die gegevens alleen met een vast wachtwoord versluiert in plaats van ze te beschermen. Eerder opgeslagen tokens blijven leesbaar, maar nieuwe worden alleen bewaard tot je de app afsluit; de kluis slaat daar nog steeds op. Installeer of ontgrendel een sleutelhanger en start GitHuttBr opnieuw.',
  'keychain.replaceStore': 'Nieuwe tokenopslag starten',
  'keychain.replaceStoreTitle': 'Nieuwe tokenopslag starten?',
  'keychain.replaceStoreMessage': 'GitHuttBr wacht niet langer op de opgeslagen tokens die het niet kan lezen en start een nieuwe opslag met alleen de tokens die je in deze sessie hebt ingevoerd. Het oude bestand blijft 30 dagen als back-up ernaast staan en wordt daarna verwijderd. Doe dit alleen als die tokens echt verloren zijn — bijvoorbeeld omdat een andere kopie van GitHuttBr ze heeft opgeslagen.',
