  'gitError.workflowScopeOAuth': 'GitHub weigerde de push: die wijzigt de workflow {file}, en deze login heeft geen `workflow`-scope. Voer bij een GitHub CLI-login `gh auth refresh -h github.com -s workflow` uit en push opnieuw.',
  'gitError.workflowScopeToken': 'GitHub weigerde de push: die wijzigt de workflow {file}, en het persoonlijke toegangstoken mag geen workflows bewerken. Geef het de scope `workflow` (klassiek token) of Workflows: Read and write (fine-grained) en push opnieuw.',
  'gitError.fileTooLarge': 'GitHub weigert bestanden boven 100 MB, en {file} is er een. Haal het uit de commits die je pusht of beheer het met Git LFS.',
