  'gitError.noCredential': 'Git heeft geen inloggegevens voor {host}. Koppel een account in Instellingen → Integraties, of meld je aan bij de credential helper van git, en probeer opnieuw.',
  'gitError.boundProfileNoCredential': "Aan het profiel ‘{profile}’ waaraan deze repository gekoppeld is, is geen {provider}-account voor {host} gekoppeld. Schakel naar dat profiel en meld je aan via Instellingen → Integraties, of voeg daar een token toe.",
  'gitError.githubNoCredentialGhMissing': 'Aan dit profiel is geen GitHub-account voor {host} gekoppeld. GitHub CLI (gh) is niet geïnstalleerd: voeg een persoonlijk toegangstoken toe via Instellingen → Integraties, of installeer gh, voer `gh auth login` uit en meld je daar aan.',
  'gitError.githubNoCredentialGhSignedOut': 'Aan dit profiel is geen GitHub-account voor {host} gekoppeld. GitHub CLI (gh) is geïnstalleerd maar niet aangemeld: voer `gh auth login` uit en meld je daarna aan via Instellingen → Integraties, of voeg daar een persoonlijk toegangstoken toe.',
  'gitError.githubNoCredentialGhUnknown': 'Aan dit profiel is geen GitHub-account voor {host} gekoppeld. Het controleren van GitHub CLI (gh) duurde te lang — misschien ben je offline. Meld je aan via Instellingen → Integraties, of voeg daar een persoonlijk toegangstoken toe.',
  'gitError.githubNoCredentialGhSignedIn': 'Aan dit profiel is geen GitHub-account voor {host} gekoppeld. GitHub CLI (gh) is aangemeld: meld je aan via Instellingen → Integraties om dat account aan dit profiel te koppelen, of voeg daar een persoonlijk toegangstoken toe.',
  'gitError.noLinkedAccount': 'Aan dit profiel is geen {provider}-account voor {host} gekoppeld. Meld je aan via Instellingen → Integraties om een login uit de credential helper van git te koppelen, of voeg daar een token toe.',
  'gitError.noLinkedAccountAnyHost': 'Aan dit profiel is geen {provider}-account gekoppeld. Meld je aan via Instellingen → Integraties om een login uit de credential helper van git te koppelen, of voeg daar een token toe.',
  'gitError.permissionDenied': 'De host weigerde schrijftoegang: het gebruikte account mag hier niet schrijven, of het token is verlopen. Controleer het actieve profiel, de toegang van het account en het token.',
  'gitError.repoNotFound': 'De server zegt dat de repository niet bestaat — of het gebruikte account kan hem niet zien. Controleer de remote-URL en het actieve profiel.',
  'gitError.sshKey': 'De server weigerde je SSH-sleutel. Controleer in Instellingen → Beveiliging welke sleutel de agent heeft, en of die aan je account is toegevoegd.',
  'gitError.tokenScope': 'Dit token mist de rechten {scopes}. De rechten van een token zijn achteraf niet te wijzigen: maak een nieuw token dat ze bevat en plak het hier.',
  'gitError.tokenScopeAny': 'Dit token heeft niet de benodigde rechten. De rechten van een token zijn achteraf niet te wijzigen: maak een nieuw token met de rechten uit de handleiding en plak het hier.',
